// Colors of the art generated by `apps/web/scripts/generate-avatar-sheets.ts`.
// Each color is [red, green, blue, alpha].
export type SheetColor = readonly [number, number, number, number];

export const GHOST_COLORS = {
    BODY: [0x65, 0x66, 0x6e, 0xff],
    // The arm and the leg that stay behind, so a turned ghost reads as a body
    // with depth.
    SHADE: [0x54, 0x55, 0x5d, 0xff],
    OUTLINE: [0xff, 0xff, 0xff, 0xff],
    EYE: [0xff, 0xff, 0xff, 0xff],
} as const satisfies Record<string, SheetColor>;

// The ghost is drawn from the torso (head, arms and body) and from legs that
// change on each frame, so the legs can really walk. Together they are as tall
// as `AVATAR.visible` without the outline.
export const GHOST_LEG_HEIGHT = 4;

