// [column, row, width, height] over the torso rows above.
export type EyeRect = readonly [number, number, number, number];

// The eyes of the ghost by direction. The ghost seen from behind has none, and
// the profile has the one eye that shows, on the side it faces.
export const GHOST_EYES = {
    down: [
        [5, 7, 2, 3],
        [11, 7, 2, 3],
    ],
    up: [],
    right: [[8, 7, 2, 3]],
} as const satisfies Record<string, readonly EyeRect[]>;

// [column, width, lift, isBehind] of one leg. `lift` is how many px the foot
// is raised off the ground, and a leg that is behind is drawn first, in shade.
export type LegPose = readonly [number, number, number, boolean];

export type GhostLegPoses = {
    IDLE: readonly LegPose[];
    // One entry for each stride of the walk.
    WALK: readonly (readonly LegPose[])[];
};

// Seen from the front or from behind the legs take turns lifting the foot.
const FRONT_LEGS_STANDING: readonly LegPose[] = [
    [2, 6, 0, false],
    [10, 6, 0, false],
];

export const GHOST_LEGS = {
    front: {
        IDLE: FRONT_LEGS_STANDING,
        WALK: [
            [
                [2, 6, 2, false],
                [10, 6, 0, false],
            ],
            [
                [2, 6, 0, false],
                [10, 6, 2, false],
            ],
        ],
    },
    // Facing right. One stride has a leg ahead and the other behind with the
    // heel up, and the next stride swaps them. The standing pose between them
    // has the legs together.
    profile: {
        IDLE: [
            [1, 5, 0, true],
            [6, 5, 0, false],
        ],
        WALK: [
            [
                [0, 5, 1, true],
                [7, 5, 0, false],
            ],
            [
                [7, 5, 1, true],
                [0, 5, 0, false],
            ],
        ],
    },
} as const satisfies Record<string, GhostLegPoses>;

// How many px the sitting figures are raised inside the frame, which is where
// the seat is under them. The sitting frames of the sheets this layout comes
// from are raised the same way.
export const SIT_LIFT_PX = 6;

// The sitting ghost keeps the top of its torso, and the rest is a lap: three
// rows with the seat under it, and for the profile the legs going forward.
export const GHOST_SIT_TORSO_ROWS = 21;

export const GHOST_SIT_LAP_ROWS = {
    down: [".################.", "##################", ".################."],
    up: [".################.", "##################", ".################."],
    right: [".############..", ".##############", ".#############."],
} as const;
